local T=dofile('tests/kernel_initialization_harness.lua');local checks=0
local function test(label,fn)fn();checks=checks+1 end
test('constructor inert',function()local r=T.unit();r.prepare();assert(#r.calls==0 and r.readyCalls==0 and r.preflights==0)end)
test('ordered one sequence',function()local r=T.unit();r.prepare();assert(r.api.Initialize()and not r.api.Initialize());assert(table.concat(r.calls,',')=='first,second,third'and r.readyCalls==1 and r.preflights==1)end)
test('false and nil initializer results allowed',function()local r=T.unit();r.spec.entries[1].handler=function()return false,nil,4,nil end;r.prepare();assert(r.api.Initialize());local v=r.api.Progress().results[1];assert(v.n==4 and v[1]==false and v[3]==4 and v[4]==nil)end)
test('descriptors/ports frozen',function()local r=T.unit();r.prepare();r.spec.entries[1].handler=function()error('mutated')end;r.ports.isReady=function()error('mutated port')end;assert(r.api.Initialize()and r.calls[1]=='first')end)
test('descriptor/result copies',function()local r=T.unit();r.prepare();r.api.Describe()[1].name='bad';r.api.Initialize();local p=r.api.Progress();p.ledger[1]='pending';p.results[1].n=10;assert(r.api.Describe()[1].name=='first'and r.api.Progress().ledger[1]=='completed'and r.api.Progress().results[1].n==1)end)
test('duplicate function rejected before ownership',function()local r=T.unit();r.spec.entries[2].handler=r.spec.entries[1].handler;assert(not pcall(r.prepare)and r.spec.owner.InitializationSequence==nil)end)
test('duplicate name rejected',function()local r=T.unit();r.spec.entries[2].name='first';assert(not pcall(r.prepare))end)
test('foreign owner preserved',function()local r=T.unit();local other={};r.spec.owner.InitializationSequence=other;assert(not pcall(r.prepare)and r.spec.owner.InitializationSequence==other)end)
test('readiness failure has no initializer effects',function()local r=T.unit();r.ready=false;r.prepare();local ok,err=r.api.Initialize();assert(not ok and err and #r.calls==0 and r.preflights==0 and not r.api.Initialize())end)
test('preflight failure has no initializer effects',function()local r=T.unit();r.spec.preflight=function()error('late hydration')end;r.prepare();assert(not r.api.Initialize()and #r.calls==0 and r.api.Progress().phase=='failed')end)
test('partial failure never replays successful prefix',function()local r=T.unit();r.spec.entries[2].handler=function()error('second failed',0)end;r.prepare();local ok,err=r.api.Initialize();local p=r.api.Progress();assert(not ok and err=='second failed'and p.ledger[1]=='completed'and p.ledger[2]=='failed'and p.ledger[3]=='pending'and not r.api.Initialize()and #r.calls==1)end)
test('cancel before initialize',function()local r=T.unit();r.prepare();assert(r.api.Cancel()and not r.api.Initialize()and #r.calls==0 and not r.api.Cancel())end)
test('cancel cannot claim rollback of completed sequence',function()local r=T.unit();r.prepare();r.api.Initialize();assert(not r.api.Cancel()and r.api.Progress().phase=='initialized'and not r.api.ReversesEffects and not r.api.StartsWorkers)end)
test('readiness reentry cannot start second sequence',function()local r=T.unit();r.readyHook=function()assert(not r.api.Initialize())end;r.prepare();assert(r.api.Initialize()and #r.calls==3)end)
test('cancel inside readiness prevents first stage',function()local r=T.unit();r.readyHook=function()r.api.Cancel()end;r.prepare();assert(not r.api.Initialize()and #r.calls==0 and r.preflights==0)end)
test('replaced graph before sequence refused',function()local r=T.unit();r.prepare();r.replaced=true;assert(not r.api.Initialize()and #r.calls==0)end)
test('replaced graph after entered stage skips suffix',function()local r=T.unit();r.spec.entries[1].handler=function()r.calls[1]='entered';r.replaced=true end;r.prepare();assert(not r.api.Initialize()and #r.calls==1 and r.api.Progress().ledger[1]=='returned-after-revocation')end)
test('cancel while awaiting keeps entered-body effects explicit',function()
    local r=T.unit();r.spec.entries[2].handler=function()coroutine.yield('await');r.lateEffect=true;return'late'end;r.prepare()
    local co=coroutine.create(function()return r.api.Initialize()end);local ok,v=coroutine.resume(co);assert(ok and v=='await'and r.api.Progress().inFlight==2)
    r.api.Cancel();local resumed,result=coroutine.resume(co);assert(resumed and result==false and r.lateEffect and #r.calls==1)
    local p=r.api.Progress();assert(p.phase=='cancelled'and p.inFlight==nil and p.ledger[2]=='returned-after-revocation'and p.ledger[3]=='pending')
end)
test('yielded readiness cancellation does not initialize',function()local r=T.unit();r.readyHook=function()coroutine.yield('ready')end;r.prepare();local co=coroutine.create(r.api.Initialize);assert(coroutine.resume(co));r.api.Cancel();assert(coroutine.resume(co)and #r.calls==0)end)
test('public State cannot revive cancelled sequence',function()local r=T.unit();r.prepare();r.api.Cancel();r.api.State='prepared-inactive';assert(not r.api.Initialize()and #r.calls==0 and r.api.Progress().phase=='cancelled')end)
print('PASS lot56 initialization: '..checks..' sequence checks; ordered unique initialization, copied results, readiness/partial failure/cancellation/late effects; no rollback/worker/teardown claim')
